+	Log* ELOG = Log::getInstance();
+	ELOG->mp_printMutex->lock();
+	ELOG->printLogMessage(lm);
+	ELOG->mp_printMutex->unlock();
+	lm.reset();
+	ELOG->mp_logMesgMutex->lock();
+	ELOG->m_logMessages.push(&lm);
+	ELOG->mp_logMesgMutex->unlock();
+}
