+
+    virtual void SetReceiveBufferSize(uint32_t size) = 0;
+    virtual void SetSendBufferSize(uint32_t size) = 0;
+    virtual void SetSocketOutbountInterface(eProsimaUDPSocket&, const std::string&) = 0;
