+    {
+        if (!checkSenderResource(*it_loc))
+        {
+            buffer = m_network_Factory.BuildSenderResources(*it_loc);
+            if (buffer.size() == 0 && ApplyMutation)
+            {
+                int tries = 0;
+                while (buffer.size() == 0 && (tries < MutationTries))
+                {
+                    tries++;
+                    *it_loc = applyLocatorAdaptRule(*it_loc);
+                    buffer = m_network_Factory.BuildSenderResources(*it_loc);
