+            {
+                std::lock_guard<std::mutex> lock(m_send_resources_mutex);
+                //Push the new items into the SenderResource buffer
+                m_senderResourceList.push_back(std::move(*it_buffer));
+            }
+            buffer.clear();
+        }
+    }
