+bool UDPTransportInterface::OpenOutputChannel(const Locator_t& locator)
+{
+    if (!IsLocatorSupported(locator) || IsOutputChannelOpen(locator))
+        return false;
+
+    return OpenAndBindOutputSockets(locator);
+}
