+        </type>
+        <type>
+            <struct name="ArrayArrayArrayStruct">
+                <member name="my_array_array_array" type="nonBasic" nonBasicTypeName="ArrayArrayStruct" arrayDimensions="2,2"/>
+            </struct>
+        </type>
