+	//	deadlineQoSlist[i].flag = false;
+	//	deadlineQoSlist[i].mtx.unlock();
+	//}
+}
+
+void deadlineQoS::runner(){
+		wait();
+		io.run();
+}
+
+void deadlineQoS::run(){
+		boost::thread dlqos(boost::bind(&deadlineQoS::runner,this));
+}
+
+void deadlineQoS::stop(){
+	t.cancel();
+	io.stop();
+}

