+
+    if(serialize_sample)
+    {
+        try
+        {
+            scdr << *sample;
+        }
+        catch(eprosima::rpc::exception::BadParamException ex)
+        {
+            //printf("ERROR<eprosima::rpc::exception::BadParamException>: %s\n", ex.what());
+            return RTI_FALSE;
+        }
