+            return RTI_FALSE;
+        }
+        catch(eprosima::fastcdr::exception::NotEnoughMemoryException ex)
+        {
+            //printf("ERROR<eprosima::fastcdr::exception::NotEnoughMemoryException>: %s\n", ex.what());
+            return RTI_FALSE;
+        }
+    }
+
+    stream->_currentPosition = scdr.getCurrentPosition();
+
